from akasha.document.codec import (
    decode_payload,
    encode_payload,
    MAX_PAYLOAD_BYTES,
)
from akasha.document.record import DocumentField
from akasha.storage.checksum import (
    BorrowedBinaryReader,
    BinaryWriter,
    crc32_range,
    crc32_update,
    CRC32_INITIAL,
)
from akasha.storage.filesystem import (
    append_file_sync,
    atomic_replace,
    path_exists,
    sync_file,
    sync_directory,
    write_file_sync,
)
from std.ffi import c_int, c_long, external_call
from std.io.file import FileHandle, O_CLOEXEC, O_WRONLY
from std.os import SEEK_END
from std.sys import size_of
from std.sys._libc_errno import get_errno


comptime _MAGIC_0 = UInt8(0x41)  # A
comptime _MAGIC_1 = UInt8(0x4B)  # K
comptime _MAGIC_2 = UInt8(0x57)  # W
comptime _MAGIC_3 = UInt8(0x4C)  # L
comptime _VERSION_V1 = UInt16(1)
comptime _VERSION_V2 = UInt16(2)
comptime _VERSION_V3 = UInt16(3)
comptime _UPSERT = UInt8(1)
comptime _DELETE = UInt8(2)
comptime _BATCH = UInt8(3)
comptime _HEADER_SIZE = 32
comptime _MIN_RECORD_SIZE = 36
comptime _MUTATION_HEADER_SIZE = 16
comptime _MAX_BATCH_RECORDS = 65_536
comptime _MAX_BATCH_BYTES = 256 * 1024 * 1024
comptime _READ_AHEAD_BYTES = 64 * 1024


struct WalRecord(Movable):
    """One decoded, checksummed mutation."""

    var sequence: UInt64
    var id: Int
    var is_delete: Bool
    var values: List[Float32]
    var fields: List[DocumentField]

    def __init__(
        out self,
        sequence: UInt64,
        id: Int,
        is_delete: Bool,
        var values: List[Float32],
    ):
        self.sequence = sequence
        self.id = id
        self.is_delete = is_delete
        self.values = values^
        self.fields = List[DocumentField]()

    @staticmethod
    def with_fields(
        sequence: UInt64,
        id: Int,
        is_delete: Bool,
        var values: List[Float32],
        var fields: List[DocumentField],
    ) -> WalRecord:
        var record = WalRecord(sequence, id, is_delete, values^)
        record.fields = fields^
        return record^

    @staticmethod
    def upsert(
        sequence: UInt64, id: Int, var values: List[Float32]
    ) -> WalRecord:
        return WalRecord(sequence, id, False, values^)

    @staticmethod
    def delete(sequence: UInt64, id: Int) -> WalRecord:
        return WalRecord(sequence, id, True, List[Float32]())

    @staticmethod
    def document_upsert(
        sequence: UInt64,
        id: Int,
        var values: List[Float32],
        var fields: List[DocumentField],
    ) -> WalRecord:
        return WalRecord.with_fields(sequence, id, False, values^, fields^)

    def take_values(mut self) -> List[Float32]:
        """Transfer decoded vectors without copying their allocation."""
        var values = self.values^
        self.values = List[Float32]()
        return values^

    def take_fields(mut self) -> List[DocumentField]:
        """Transfer decoded payload fields without copying their allocation."""
        var fields = self.fields^
        self.fields = List[DocumentField]()
        return fields^


struct WalReplayState(Movable):
    """Owned replay results and lengths for deferred accepted-tail repair."""

    var records: List[WalRecord]
    var valid_length: Int
    var source_length: Int

    def __init__(
        out self,
        var records: List[WalRecord],
        valid_length: Int,
        source_length: Int,
    ):
        self.records = records^
        self.valid_length = valid_length
        self.source_length = source_length

    def needs_repair(self) -> Bool:
        return self.valid_length < self.source_length

    def take_records(deinit self) -> List[WalRecord]:
        return self.records^


struct WalReader(Movable):
    """Read and validate one complete WAL envelope at a time.

    The input buffer is bounded by the largest accepted envelope or 64 KiB,
    independent of total WAL length. Returned mutations own their values; no view survives
    the next buffer refill. The caller must hold collection write exclusion
    while consuming the WAL and applying a deferred repair.
    """

    var _file: FileHandle
    var _buffer: List[UInt8]
    var _buffer_offset: Int
    var _dimension: Int
    var _previous_sequence: UInt64
    var _done: Bool
    var _failed: Bool
    var valid_length: Int
    var source_length: Int

    def __init__(out self, path: String, dimension: Int) raises:
        self._file = FileHandle()
        self._buffer = List[UInt8]()
        self._buffer_offset = 0
        self._dimension = dimension
        self._previous_sequence = 0
        self._done = False
        self._failed = False
        self.valid_length = 0
        self.source_length = 0
        if not path_exists(path):
            self._done = True
            return
        _validate_dimension(dimension)
        self._file = open(path, "r")
        var length = self._file.seek(0, SEEK_END)
        if length > UInt64(Int.MAX):
            raise Error("WAL file is too large")
        self.source_length = Int(length)
        _ = self._file.seek(0)

    def read_next(mut self) raises -> List[WalRecord]:
        if self._failed:
            raise Error("cannot resume a failed WAL reader")
        var remaining = self.source_length - self.valid_length
        if self._done or remaining < _HEADER_SIZE:
            self._done = True
            return List[WalRecord]()
        # An exception may leave the descriptor past a corrupt envelope. Do
        # not let a caught error turn a later read into accepted recovery.
        self._failed = True
        self._ensure_available(_HEADER_SIZE)
        var record_size = _envelope_size(
            Span(self._buffer)[self._buffer_offset :], self._dimension
        )
        if remaining < record_size:
            self._done = True
            self._failed = False
            return List[WalRecord]()
        self._ensure_available(record_size)
        var records = _decode_envelope(
            Span(self._buffer)[
                self._buffer_offset : self._buffer_offset + record_size
            ],
            self._dimension,
            self._previous_sequence,
        )
        self._previous_sequence = records[len(records) - 1].sequence
        self._buffer_offset += record_size
        self.valid_length += record_size
        self._failed = False
        return records^

    def _ensure_available(mut self, count: Int) raises:
        var retained = len(self._buffer) - self._buffer_offset
        if retained >= count:
            return
        # Compact only an envelope prefix crossing a read boundary. No view
        # from a previous decode survives here; copying forward handles overlap.
        if self._buffer_offset > 0:
            for i in range(retained):
                self._buffer[i] = self._buffer[self._buffer_offset + i]
        var target = min(
            self.source_length - self.valid_length,
            max(_READ_AHEAD_BYTES, count),
        )
        self._buffer.resize(target, 0)
        self._buffer_offset = 0
        _read_exact(self._file, Span(self._buffer)[retained:])


def _read_exact[
    origin: MutOrigin
](file: FileHandle, bytes: Span[UInt8, origin]) raises:
    var offset = 0
    while offset < len(bytes):
        var count = file.read(bytes[offset:])
        if count == 0:
            raise Error("WAL changed during preflight")
        offset += count


def encode_upsert(
    sequence: UInt64,
    id: Int,
    dimension: Int,
    values: List[Float32],
) raises -> List[UInt8]:
    if dimension <= 0 or len(values) != dimension:
        raise Error("WAL upsert dimension mismatch")
    var fields = List[DocumentField]()
    return _encode_record(sequence, id, dimension, _UPSERT, values, fields)


def encode_document_upsert(
    sequence: UInt64,
    id: Int,
    dimension: Int,
    values: List[Float32],
    fields: List[DocumentField],
) raises -> List[UInt8]:
    if dimension <= 0 or len(values) != dimension:
        raise Error("WAL upsert dimension mismatch")
    return _encode_record(sequence, id, dimension, _UPSERT, values, fields)


def encode_delete(
    sequence: UInt64, id: Int, dimension: Int
) raises -> List[UInt8]:
    if dimension <= 0:
        raise Error("WAL dimension must be positive")
    var empty = List[Float32]()
    var fields = List[DocumentField]()
    return _encode_record(sequence, id, dimension, _DELETE, empty, fields)


def append_wal(path: String, dimension: Int, record: WalRecord) raises:
    var bytes: List[UInt8]
    if record.is_delete:
        bytes = encode_delete(record.sequence, record.id, dimension)
    else:
        bytes = encode_document_upsert(
            record.sequence,
            record.id,
            dimension,
            record.values,
            record.fields,
        )
    append_file_sync(path, bytes)


def append_wal_batch(
    path: String, dimension: Int, records: List[WalRecord]
) raises:
    """Append and fsync one atomic v3 mutation envelope."""
    var bytes = encode_batch(dimension, records)
    append_file_sync(path, bytes)


def encode_batch(
    dimension: Int, records: List[WalRecord]
) raises -> List[UInt8]:
    if dimension <= 0:
        raise Error("WAL dimension must be positive")
    if len(records) == 0:
        raise Error("WAL batch cannot be empty")
    if len(records) > _MAX_BATCH_RECORDS:
        raise Error("WAL batch record count is too large")
    var first_sequence = records[0].sequence
    if first_sequence == 0:
        raise Error("WAL sequence must be positive")
    if first_sequence > UInt64.MAX - UInt64(len(records) - 1):
        raise Error("WAL batch sequence range overflows")

    var body = BinaryWriter()
    for index in range(len(records)):
        if records[index].sequence != first_sequence + UInt64(index):
            raise Error("WAL batch sequences must be contiguous")
        body.write_u8(_DELETE if records[index].is_delete else _UPSERT)
        body.write_u8(0)
        body.write_u16(0)
        body.write_i64(Int64(records[index].id))
        if records[index].is_delete:
            if (
                len(records[index].values) != 0
                or len(records[index].fields) != 0
            ):
                raise Error("WAL delete cannot contain values or fields")
            body.write_u32(0)
            continue
        if len(records[index].values) != dimension:
            raise Error("WAL upsert dimension mismatch")
        var payload = encode_payload(records[index].fields)
        var mutation_size = dimension * 4 + 4 + len(payload)
        body.write_u32(UInt32(mutation_size))
        for value in records[index].values:
            body.write_f32(value)
        body.write_u32(UInt32(len(payload)))
        body.write_bytes(payload)

    var body_bytes = body.take_bytes()
    var record_size = _HEADER_SIZE + len(body_bytes) + 4
    if record_size > _MAX_BATCH_BYTES:
        raise Error("WAL batch encoded size is too large")
    var writer = BinaryWriter()
    writer.write_u8(_MAGIC_0)
    writer.write_u8(_MAGIC_1)
    writer.write_u8(_MAGIC_2)
    writer.write_u8(_MAGIC_3)
    writer.write_u16(_VERSION_V3)
    writer.write_u8(_BATCH)
    writer.write_u8(0)
    writer.write_u32(UInt32(record_size))
    writer.write_u64(first_sequence)
    writer.write_u32(UInt32(len(records)))
    writer.write_u32(UInt32(dimension))
    writer.write_u32(0)
    writer.write_bytes(body_bytes)
    var encoded = writer.take_bytes()
    var checksum = crc32_range(encoded, 4, len(encoded))
    var complete = BinaryWriter()
    complete.write_bytes(encoded)
    complete.write_u32(checksum)
    return complete.take_bytes()


def rotate_wal(directory: String) raises:
    """Atomically replace the collection WAL with a durable empty file."""
    var temporary_path = directory + "/wal.bin.tmp"
    var final_path = directory + "/wal.bin"
    var empty = List[UInt8]()
    write_file_sync(temporary_path, empty)
    atomic_replace(temporary_path, final_path)
    sync_directory(directory)


def replay_wal(path: String, dimension: Int) raises -> List[WalRecord]:
    var replay = preflight_wal(path, dimension)
    return replay^.take_records()


def recover_wal(path: String, dimension: Int) raises -> List[WalRecord]:
    """Replay a WAL and durably remove an accepted torn EOF tail."""
    var replay = preflight_wal(path, dimension)
    repair_wal_tail(path, replay)
    return replay^.take_records()


def preflight_wal(path: String, dimension: Int) raises -> WalReplayState:
    """Decode without modifying a missing file or accepted torn tail.

    This owned-result API retains decoded records, but never the complete
    encoded WAL or a copied repair prefix. Recovery can consume WalReader
    directly when it does not need to retain the complete history.
    """
    var reader = WalReader(path, dimension)
    var records = List[WalRecord]()
    while True:
        var batch = reader.read_next()
        if len(batch) == 0:
            break
        for var record in batch^:
            records.append(record^)
    return WalReplayState(records^, reader.valid_length, reader.source_length)


def repair_wal_tail(path: String, replay: WalReplayState) raises:
    """Apply only the tail repair established by ``preflight_wal``."""
    repair_wal_tail(path, replay.valid_length, replay.source_length)


def repair_wal_tail(path: String, valid_length: Int, source_length: Int) raises:
    """Truncate a preflighted WAL under the caller's collection exclusion.

    Never create a missing WAL or rewrite accepted bytes. Length changes since
    preflight are rejected before the first mutation. Complete all other source
    validation before calling this function.
    """
    comptime assert size_of[c_long]() == 8, "64-bit POSIX off_t required"
    if valid_length < 0 or valid_length > source_length:
        raise Error("invalid WAL repair length")
    if valid_length == source_length:
        return
    var file_path = path.copy()
    var descriptor = external_call["open", c_int, num_fixed_args=2](
        file_path.as_c_string_slice(), c_int(O_WRONLY | O_CLOEXEC)
    )
    if descriptor < 0:
        raise Error("open WAL for repair failed: " + String(get_errno()))
    var file = FileHandle()
    file.handle = Int(descriptor)
    if file.seek(0, SEEK_END) != UInt64(source_length):
        raise Error("WAL changed after preflight")
    if external_call["ftruncate", c_int](descriptor, c_long(valid_length)) != 0:
        raise Error("WAL tail truncate failed: " + String(get_errno()))
    sync_file(file)


def decode_wal_bytes(
    var bytes: List[UInt8], dimension: Int
) raises -> List[WalRecord]:
    return decode_wal_bytes(Span(bytes), dimension)


def decode_wal_bytes(
    bytes: Span[UInt8, _], dimension: Int
) raises -> List[WalRecord]:
    _validate_dimension(dimension)
    var records = List[WalRecord]()
    var offset = 0
    var previous_sequence = UInt64(0)
    while len(bytes) - offset >= _HEADER_SIZE:
        var record_size = _envelope_size(bytes[offset:], dimension)
        if len(bytes) - offset < record_size:
            break
        var batch = _decode_envelope(
            bytes[offset : offset + record_size], dimension, previous_sequence
        )
        previous_sequence = batch[len(batch) - 1].sequence
        for var record in batch^:
            records.append(record^)
        offset += record_size
    return records^


def _validate_dimension(dimension: Int) raises:
    if dimension <= 0 or dimension > Int(UInt32.MAX):
        raise Error("WAL dimension must be positive and fit UInt32")


def _envelope_size(bytes: Span[UInt8, _], dimension: Int) raises -> Int:
    # Both callers guarantee a complete 32-byte header. Preserve validation
    # order: bad magic/length fail even at EOF; other fields wait for a whole
    # envelope, so a torn final v3 batch yields none of its mutations.
    if not _has_magic(bytes):
        raise Error("invalid WAL record magic")
    var version = UInt16(bytes[4]) | (UInt16(bytes[5]) << UInt16(8))
    var maximum_size = 40 + dimension * 4 + MAX_PAYLOAD_BYTES
    if version == _VERSION_V3:
        maximum_size = _MAX_BATCH_BYTES
    var record_size = _read_u32_at(bytes, 8)
    if record_size < _MIN_RECORD_SIZE or record_size > maximum_size:
        raise Error("invalid WAL record length")
    return record_size


def _decode_envelope(
    bytes: Span[UInt8, _], dimension: Int, previous_sequence: UInt64
) raises -> List[WalRecord]:
    var records = List[WalRecord]()
    var version = UInt16(bytes[4]) | (UInt16(bytes[5]) << UInt16(8))
    if version == _VERSION_V3:
        if bytes[6] != _BATCH:
            raise Error("invalid WAL v3 operation")
        _ = _decode_batch(bytes, dimension, previous_sequence, records)
    else:
        var record = _decode_record(bytes, dimension)
        if record.sequence <= previous_sequence:
            raise Error("WAL sequence must increase")
        records.append(record^)
    return records^


def _decode_batch(
    bytes: Span[UInt8, _],
    expected_dimension: Int,
    previous_sequence: UInt64,
    mut records: List[WalRecord],
) raises -> UInt64:
    var encoded_size = len(bytes)
    var stored_checksum = _read_u32_at(bytes, encoded_size - 4)
    if ~crc32_update(CRC32_INITIAL, bytes[4 : encoded_size - 4]) != UInt32(
        stored_checksum
    ):
        raise Error("WAL checksum mismatch")

    var reader = BorrowedBinaryReader(bytes)
    if (
        reader.read_u8() != _MAGIC_0
        or reader.read_u8() != _MAGIC_1
        or reader.read_u8() != _MAGIC_2
        or reader.read_u8() != _MAGIC_3
    ):
        raise Error("invalid WAL record magic")
    if reader.read_u16() != _VERSION_V3 or reader.read_u8() != _BATCH:
        raise Error("invalid WAL v3 batch header")
    if reader.read_u8() != 0:
        raise Error("unsupported WAL flags")
    if Int(reader.read_u32()) != encoded_size:
        raise Error("WAL record length mismatch")
    var first_sequence = reader.read_u64()
    var count_u32 = reader.read_u32()
    var count = Int(count_u32)
    if count == 0 or count > _MAX_BATCH_RECORDS:
        raise Error("invalid WAL batch record count")
    var dimension = Int(reader.read_u32())
    if dimension != expected_dimension:
        raise Error("WAL dimension mismatch")
    if reader.read_u32() != 0:
        raise Error("unsupported WAL batch reserved field")
    if first_sequence == 0 or first_sequence <= previous_sequence:
        raise Error("WAL sequence must increase")
    if first_sequence > UInt64.MAX - UInt64(count - 1):
        raise Error("WAL batch sequence range overflows")

    for index in range(count):
        var operation = reader.read_u8()
        if operation != _UPSERT and operation != _DELETE:
            raise Error("invalid WAL batch mutation operation")
        if reader.read_u8() != 0 or reader.read_u16() != 0:
            raise Error("unsupported WAL batch mutation flags")
        var id = Int(reader.read_i64())
        var mutation_size = Int(reader.read_u32())
        var sequence = first_sequence + UInt64(index)
        if operation == _DELETE:
            if mutation_size != 0:
                raise Error("WAL batch delete cannot contain a body")
            records.append(WalRecord.delete(sequence, id))
            continue

        if mutation_size < dimension * 4 + 4:
            raise Error("WAL batch upsert body is truncated")
        var values = List[Float32](capacity=dimension)
        for _ in range(dimension):
            values.append(reader.read_f32())
        var payload_length = Int(reader.read_u32())
        if mutation_size != dimension * 4 + 4 + payload_length:
            raise Error("WAL batch mutation length mismatch")
        var payload = reader.read_span(payload_length)
        var fields = decode_payload(payload)
        records.append(
            WalRecord.document_upsert(sequence, id, values^, fields^)
        )

    _ = reader.read_u32()
    if reader.remaining() != 0:
        raise Error("unexpected WAL batch payload")
    return first_sequence + UInt64(count - 1)


def _encode_record(
    sequence: UInt64,
    id: Int,
    dimension: Int,
    operation: UInt8,
    values: List[Float32],
    fields: List[DocumentField],
) raises -> List[UInt8]:
    if sequence == 0:
        raise Error("WAL sequence must be positive")
    var payload = List[UInt8]()
    if operation == _UPSERT:
        payload = encode_payload(fields)
    elif len(fields) != 0:
        raise Error("WAL delete cannot contain fields")
    var vector_size = 0 if operation == _DELETE else dimension * 4
    var record_size = 40 + vector_size + len(payload)

    var writer = BinaryWriter()
    writer.write_u8(_MAGIC_0)
    writer.write_u8(_MAGIC_1)
    writer.write_u8(_MAGIC_2)
    writer.write_u8(_MAGIC_3)
    writer.write_u16(_VERSION_V2)
    writer.write_u8(operation)
    writer.write_u8(0)
    writer.write_u32(UInt32(record_size))
    writer.write_u64(sequence)
    writer.write_i64(Int64(id))
    writer.write_u32(UInt32(dimension))
    if operation == _UPSERT:
        for value in values:
            writer.write_f32(value)
    writer.write_u32(UInt32(len(payload)))
    writer.write_bytes(payload)

    var body = writer.take_bytes()
    var checksum = crc32_range(body, 4, len(body))
    var complete = BinaryWriter()
    complete.write_bytes(body)
    complete.write_u32(checksum)
    return complete.take_bytes()


def _decode_record(
    bytes: Span[UInt8, _], expected_dimension: Int
) raises -> WalRecord:
    var encoded_size = len(bytes)
    var stored_checksum = _read_u32_at(bytes, len(bytes) - 4)
    if ~crc32_update(CRC32_INITIAL, bytes[4 : len(bytes) - 4]) != UInt32(
        stored_checksum
    ):
        raise Error("WAL checksum mismatch")

    var reader = BorrowedBinaryReader(bytes)
    if (
        reader.read_u8() != _MAGIC_0
        or reader.read_u8() != _MAGIC_1
        or reader.read_u8() != _MAGIC_2
        or reader.read_u8() != _MAGIC_3
    ):
        raise Error("invalid WAL record magic")
    var version = reader.read_u16()
    if version != _VERSION_V1 and version != _VERSION_V2:
        raise Error("unsupported WAL version")
    var operation = reader.read_u8()
    if operation != _UPSERT and operation != _DELETE:
        raise Error("invalid WAL operation")
    if reader.read_u8() != 0:
        raise Error("unsupported WAL flags")
    var record_size = Int(reader.read_u32())
    if record_size != encoded_size:
        raise Error("WAL record length mismatch")
    var sequence = reader.read_u64()
    if sequence == 0:
        raise Error("WAL sequence must be positive")
    var id = Int(reader.read_i64())
    var dimension = Int(reader.read_u32())
    if dimension != expected_dimension:
        raise Error("WAL dimension mismatch")

    var values = List[Float32](capacity=dimension)
    if operation == _UPSERT:
        for _ in range(dimension):
            values.append(reader.read_f32())
    var fields = List[DocumentField]()
    if version == _VERSION_V2:
        var payload_length = Int(reader.read_u32())
        if operation == _DELETE and payload_length != 0:
            raise Error("WAL delete cannot contain payload")
        var payload = reader.read_span(payload_length)
        if operation == _UPSERT:
            fields = decode_payload(payload)
    _ = reader.read_u32()
    if reader.remaining() != 0:
        raise Error("unexpected WAL payload")
    return WalRecord.with_fields(
        sequence, id, operation == _DELETE, values^, fields^
    )


def _has_magic(bytes: Span[UInt8, _]) -> Bool:
    return (
        bytes[0] == _MAGIC_0
        and bytes[1] == _MAGIC_1
        and bytes[2] == _MAGIC_2
        and bytes[3] == _MAGIC_3
    )


def _read_u32_at(bytes: Span[UInt8, _], offset: Int) -> Int:
    return Int(
        UInt32(bytes[offset])
        | (UInt32(bytes[offset + 1]) << UInt32(8))
        | (UInt32(bytes[offset + 2]) << UInt32(16))
        | (UInt32(bytes[offset + 3]) << UInt32(24))
    )

tests/mojo/test_wal_stream.mojo.text:
from akasha.document import DocumentField, PayloadValue
from akasha.storage.checksum import BinaryWriter, crc32_range
from akasha.storage.filesystem import (
    append_file_sync,
    path_exists,
    read_file_bytes,
    remove_file_if_exists,
    write_file_sync,
)
from akasha.storage.wal import (
    WalReader,
    WalRecord,
    decode_wal_bytes,
    encode_batch,
    encode_delete,
    encode_document_upsert,
    preflight_wal,
    repair_wal_tail,
    recover_wal,
)
from std.testing import assert_equal, assert_raises, TestSuite


def _mixed_wal() raises -> List[UInt8]:
    var writer = BinaryWriter()
    writer.write_bytes([UInt8(0x41), 0x4B, 0x57, 0x4C])
    writer.write_u16(1)
    writer.write_u8(1)
    writer.write_u8(0)
    writer.write_u32(40)
    writer.write_u64(1)
    writer.write_i64(-9)
    writer.write_u32(1)
    writer.write_f32(-3.0)
    var bytes = writer.take_bytes()
    var checksum = crc32_range(bytes, 4, len(bytes))
    writer.write_bytes(bytes)
    writer.write_u32(checksum)
    var fields: List[DocumentField] = [
        DocumentField("message", PayloadValue.string("借用" * 100)),
    ]
    var v2 = encode_document_upsert(2, 12, 1, [4.0], fields)
    writer.write_bytes(v2)
    var records = List[WalRecord]()
    records.append(WalRecord.delete(3, -9))
    records.append(WalRecord.upsert(4, 13, [5.0]))
    var v3 = encode_batch(1, records)
    writer.write_bytes(v3)
    return writer.take_bytes()


def _assert_records_equal(left: List[WalRecord], right: List[WalRecord]) raises:
    assert_equal(len(left), len(right))
    for i in range(len(left)):
        assert_equal(left[i].sequence, right[i].sequence)
        assert_equal(left[i].id, right[i].id)
        assert_equal(left[i].is_delete, right[i].is_delete)
        assert_equal(len(left[i].values), len(right[i].values))
        for j in range(len(left[i].values)):
            assert_equal(left[i].values[j], right[i].values[j])
        assert_equal(len(left[i].fields), len(right[i].fields))
        for j in range(len(left[i].fields)):
            assert_equal(left[i].fields[j].name, right[i].fields[j].name)
            assert_equal(
                left[i].fields[j].value.as_string(),
                right[i].fields[j].value.as_string(),
            )


def test_stream_returns_complete_envelopes_and_owns_returned_values() raises:
    var path = String("/tmp/akasha-wal-stream-owned.bin")
    var bytes = _mixed_wal()
    write_file_sync(path, bytes)
    var reader = WalReader(path, 1)
    assert_equal(reader.valid_length, 0)
    assert_equal(reader.source_length, len(bytes))
    var v1 = reader.read_next()
    assert_equal(len(v1), 1)
    assert_equal(v1[0].id, -9)
    assert_equal(reader.valid_length, 40)
    var v2 = reader.read_next()
    var v3 = reader.read_next()
    assert_equal(len(v3), 2)
    assert_equal(v3[0].is_delete, True)
    assert_equal(v3[1].values[0], Float32(5))
    assert_equal(reader.valid_length, len(bytes))
    assert_equal(len(reader.read_next()), 0)
    assert_equal(len(reader.read_next()), 0)
    assert_equal(v1[0].values[0], Float32(-3))
    assert_equal(v2[0].fields[0].value.as_string(), "借用" * 100)
    remove_file_if_exists(path)


def test_recovered_mutation_transfers_owned_buffers_without_copying() raises:
    var fields: List[DocumentField] = [
        DocumentField("body", PayloadValue.string("transfer" * 100)),
    ]
    var record = WalRecord.document_upsert(1, -9, [3.0], fields^)
    var vector_address = Int(record.values.unsafe_ptr())
    var fields_address = Int(record.fields.unsafe_ptr())
    var values = record.take_values()
    var payload = record.take_fields()
    assert_equal(Int(values.unsafe_ptr()), vector_address)
    assert_equal(Int(payload.unsafe_ptr()), fields_address)
    assert_equal(values[0], Float32(3))
    assert_equal(payload[0].value.as_string(), "transfer" * 100)


def test_stream_and_span_match_owned_decoder_at_every_torn_boundary() raises:
    var path = String("/tmp/akasha-wal-stream-cuts.bin")
    var bytes = _mixed_wal()
    var second_end = 40 + Int(
        UInt32(bytes[48])
        | UInt32(bytes[49]) << 8
        | UInt32(bytes[50]) << 16
        | UInt32(bytes[51]) << 24
    )
    for cut in range(len(bytes) + 1):
        var prefix = List[UInt8]()
        prefix.extend(Span(bytes)[:cut])
        # This fixture is not a durability test; avoid a sync for every cut.
        with open(path, "w") as file:
            file.write_all(Span(prefix))
        var expected = decode_wal_bytes(prefix.copy(), 1)
        var borrowed = decode_wal_bytes(Span(prefix), 1)
        var streamed = preflight_wal(path, 1)
        _assert_records_equal(expected, borrowed)
        _assert_records_equal(expected, streamed.records)
        var accepted = (
            len(bytes) if cut
            == len(bytes) else second_end if cut
            >= second_end else 40 if cut
            >= 40 else 0
        )
        var count = (
            4 if cut
            == len(bytes) else 2 if cut
            >= second_end else 1 if cut
            >= 40 else 0
        )
        assert_equal(len(expected), count)
        assert_equal(streamed.valid_length, accepted)
        assert_equal(streamed.source_length, cut)
    remove_file_if_exists(path)


def test_stream_rejects_file_shrinking_during_preflight() raises:
    var path = String("/tmp/akasha-wal-stream-shrink.bin")
    var bytes = _mixed_wal()
    write_file_sync(path, bytes)
    var reader = WalReader(path, 1)
    write_file_sync(path, [])
    with assert_raises():
        _ = reader.read_next()
    assert_equal(reader.valid_length, 0)
    remove_file_if_exists(path)


def test_failed_stream_cannot_resume_past_corrupt_envelope() raises:
    var path = String("/tmp/akasha-wal-stream-failed.bin")
    var bytes = _mixed_wal()
    bytes[36] ^= 1  # First v1 envelope CRC; the following v2/v3 remain valid.
    write_file_sync(path, bytes)
    var reader = WalReader(path, 1)
    with assert_raises():
        _ = reader.read_next()
    with assert_raises():
        _ = reader.read_next()
    assert_equal(reader.valid_length, 0)
    remove_file_if_exists(path)


def test_envelopes_cross_read_boundaries_and_grow_beyond_read_ahead() raises:
    var path = String("/tmp/akasha-wal-stream-boundaries.bin")
    var sizes: List[Int] = [0, 65000, 500, 131072, 0]
    with open(path, "w") as file:
        for i in range(len(sizes)):
            var fields: List[DocumentField] = [
                DocumentField("text", PayloadValue.string("x" * sizes[i])),
            ]
            var bytes = encode_document_upsert(
                UInt64(i + 1), i, 1, [Float32(i)], fields
            )
            file.write_all(Span(bytes))
    var reader = WalReader(path, 1)
    for i in range(len(sizes)):
        var records = reader.read_next()
        assert_equal(len(records), 1)
        assert_equal(records[0].id, i)
        assert_equal(records[0].values[0], Float32(i))
        assert_equal(records[0].fields[0].value.as_string(), "x" * sizes[i])
    assert_equal(len(reader.read_next()), 0)
    assert_equal(reader.valid_length, reader.source_length)
    remove_file_if_exists(path)


def test_preflight_defers_repair_and_truncate_preserves_prefix_and_append() raises:
    var path = String("/tmp/akasha-wal-stream-repair.bin")
    var bytes = _mixed_wal()
    write_file_sync(path, bytes)
    append_file_sync(path, [UInt8(0x41), 0x4B, 0x57])
    var state = preflight_wal(path, 1)
    assert_equal(state.needs_repair(), True)
    assert_equal(len(read_file_bytes(path)), len(bytes) + 3)
    repair_wal_tail(path, state)
    var repaired = read_file_bytes(path)
    assert_equal(len(repaired), len(bytes))
    for i in range(len(bytes)):
        assert_equal(repaired[i], bytes[i])
    var deleted = encode_delete(5, 13, 1)
    append_file_sync(path, deleted)
    var records = recover_wal(path, 1)
    assert_equal(len(records), 5)
    assert_equal(records[4].sequence, UInt64(5))
    remove_file_if_exists(path)


def test_repair_rejects_changed_length_or_missing_file_without_overwriting() raises:
    var path = String("/tmp/akasha-wal-stream-stale.bin")
    var bytes = _mixed_wal()
    write_file_sync(path, bytes)
    append_file_sync(path, [UInt8(1)])
    var state = preflight_wal(path, 1)
    append_file_sync(path, [UInt8(2)])
    with assert_raises():
        repair_wal_tail(path, state)
    assert_equal(len(read_file_bytes(path)), len(bytes) + 2)
    remove_file_if_exists(path)
    with assert_raises():
        repair_wal_tail(path, state)
    assert_equal(path_exists(path), False)


def test_stream_rejects_complete_corruption_and_invalid_header_lengths() raises:
    var path = String("/tmp/akasha-wal-stream-invalid.bin")
    var bytes = _mixed_wal()
    bytes[len(bytes) - 1] ^= 1
    write_file_sync(path, bytes)
    with assert_raises():
        _ = preflight_wal(path, 1)
    assert_equal(len(read_file_bytes(path)), len(bytes))
    for record_size in [0, 35, Int(UInt32.MAX)]:
        var header = List[UInt8]()
        header.extend(Span(bytes)[:32])
        for i in range(4):
            header[8 + i] = UInt8(UInt32(record_size) >> UInt32(8 * i))
        write_file_sync(path, header)
        with assert_raises():
            _ = preflight_wal(path, 1)
    remove_file_if_exists(path)


def test_stream_missing_and_empty_files_have_no_mutations_or_repair() raises:
    var path = String("/tmp/akasha-wal-stream-empty.bin")
    remove_file_if_exists(path)
    var missing = preflight_wal(path, 1)
    assert_equal(len(missing.records), 0)
    assert_equal(missing.needs_repair(), False)
    repair_wal_tail(path, missing)
    assert_equal(path_exists(path), False)
    write_file_sync(path, [])
    var empty = preflight_wal(path, 1)
    assert_equal(empty.valid_length, 0)
    assert_equal(empty.source_length, 0)
    with assert_raises():
        _ = preflight_wal(path, 0)
    remove_file_if_exists(path)


def main() raises:
    TestSuite.discover_tests[__functions_in_module()]().run()

benchmarks/mojo/wal_decode_bench.mojo.text:
"""Measure owned replay and collection recovery in fresh processes.

Prepare fixtures separately; each record replaces one of a fixed set of IDs.
History grows without increasing the final authority size. No benchmark API
depends on the streaming implementation, so the same source builds before/after.
"""

from akasha import DocumentField, PayloadValue, PersistentCollection
from akasha.storage.filesystem import ensure_directory, sync_file
from akasha.storage.wal import (
    encode_delete,
    encode_document_upsert,
    preflight_wal,
)
from std.sys.arg import argv
from std.time import perf_counter_ns


def _vector(sequence: Int, dimension: Int) -> List[Float32]:
    var values = List[Float32](capacity=dimension)
    for column in range(dimension):
        values.append(Float32(sequence) + Float32(column) * 0.25)
    return values^


def _payload(sequence: Int, width: Int) -> String:
    return "x" * width + String(sequence)


def _prepare(
    path: String, count: Int, live: Int, dimension: Int, width: Int
) raises:
    ensure_directory(path)
    with open(path + "/wal.bin", "w") as file:
        for sequence in range(1, count + 1):
            var id = (sequence - 1) % live
            var bytes: List[UInt8]
            if sequence % 17 == 0:
                bytes = encode_delete(UInt64(sequence), id, dimension)
            else:
                var fields: List[DocumentField] = [
                    DocumentField(
                        "payload",
                        PayloadValue.string(_payload(sequence, width)),
                    ),
                ]
                var values = _vector(sequence, dimension)
                bytes = encode_document_upsert(
                    UInt64(sequence), id, dimension, values, fields
                )
            file.write_all(Span(bytes))
        sync_file(file)


def main() raises:
    var args = argv()
    if len(args) != 7:
        raise Error(
            "usage: wal-decode-bench prepare|replay|open PATH RECORDS LIVE"
            " DIMENSION PAYLOAD_BYTES"
        )
    var count = Int(args[3])
    var live = Int(args[4])
    var dimension = Int(args[5])
    var width = Int(args[6])
    if count < live or live <= 0 or dimension <= 0 or width < 0:
        raise Error("invalid WAL benchmark sizes")
    if args[1] == "prepare":
        _prepare(args[2], count, live, dimension, width)
        return
    var started = perf_counter_ns()
    var elapsed: Int
    var digest = UInt64(0)
    if args[1] == "replay":
        var replay = preflight_wal(args[2] + "/wal.bin", dimension)
        elapsed = perf_counter_ns() - started
        if len(replay.records) != count or replay.needs_repair():
            raise Error("replay lost a record")
        for i in range(count):
            ref record = replay.records[i]
            var sequence = i + 1
            if (
                record.sequence != UInt64(sequence)
                or record.id != i % live
                or record.is_delete != (sequence % 17 == 0)
            ):
                raise Error("replay record identity mismatch")
            if not record.is_delete:
                if (
                    len(record.values) != dimension
                    or record.values[0] != Float32(sequence)
                    or record.values[dimension - 1]
                    != Float32(sequence) + Float32(dimension - 1) * 0.25
                    or record.fields[0].value.as_string()
                    != _payload(sequence, width)
                ):
                    raise Error("replay record content mismatch")
            digest += record.sequence
    elif args[1] == "open":
        var collection = PersistentCollection.open(
            args[2],
            dimension,
            maintenance_library_path="/akasha-bench-no-worker",
        )
        elapsed = perf_counter_ns() - started
        if collection.last_sequence() != UInt64(count):
            raise Error("recovery sequence mismatch")
        for id in range(live):
            var sequence = count - (count - 1 - id) % live
            var record = collection.get(id)
            if sequence % 17 == 0:
                if record:
                    raise Error("recovery resurrected deleted point")
                continue
            if not record:
                raise Error("recovery lost live point")
            ref point = record.value()
            if (
                len(point.vector) != dimension
                or point.vector[0] != Float32(sequence)
                or point.vector[dimension - 1]
                != Float32(sequence) + Float32(dimension - 1) * 0.25
                or point.get_field("payload").value().as_string()
                != _payload(sequence, width)
            ):
                raise Error("recovery latest-state mismatch")
            digest += UInt64(sequence)
        collection.close()
    else:
        raise Error("invalid WAL benchmark mode")
    print(
        "mode="
        + args[1]
        + " records="
        + String(count)
        + " live="
        + String(live)
